package com.owuor.educue.certificate.service;
import com.owuor.educue.certificate.entity.*;import com.owuor.educue.certificate.enums.*;import com.owuor.educue.certificate.repository.*;import com.owuor.educue.graduation.enums.*;import com.owuor.educue.graduation.repository.*;import lombok.RequiredArgsConstructor;import org.springframework.scheduling.annotation.Async;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.*;import org.springframework.transaction.event.*;import java.time.*;import java.util.*;
@Service @RequiredArgsConstructor public class CertificateJobWorker{private final CertificateGenerationJobRepository jobRepository;private final GraduationBatchCandidateRepository candidateRepository;private final CertificateItemWorker itemWorker;
 @Async @TransactionalEventListener(phase=TransactionPhase.AFTER_COMMIT) public void run(CertificateJobService.GenerateCertificatesEvent event){start(event.jobId());try{var job=jobRepository.findById(event.jobId()).orElseThrow();var candidateIds=candidateRepository.findByBatchIdAndStatusOrderByIdAsc(job.getBatch().getId(),GraduationBatchCandidateStatus.GRADUATED).stream().map(c->c.getId()).toList();for(Long id:candidateIds)itemWorker.generate(event.jobId(),id);finish(event.jobId(),null);}catch(Exception e){finish(event.jobId(),e.getMessage());}}
 @Async @TransactionalEventListener(phase=TransactionPhase.AFTER_COMMIT) public void retry(CertificateJobService.RetryCertificateEvent event){try{itemWorker.generate(event.jobId(),event.candidateId());finish(event.jobId(),null);}catch(Exception e){finish(event.jobId(),e.getMessage());}}
 @Transactional public void start(Long id){var j=jobRepository.findById(id).orElseThrow();j.setStatus(CertificateJobStatus.PROCESSING);j.setStartedAt(LocalDateTime.now());jobRepository.save(j);}
 @Transactional public void finish(Long id,String fatal){var j=jobRepository.findById(id).orElseThrow();j.setCompletedAt(LocalDateTime.now());if(fatal!=null){j.setStatus(CertificateJobStatus.FAILED);j.setErrorMessage(fatal.substring(0,Math.min(1000,fatal.length())));}else j.setStatus(j.getFailedCertificates()>0?CertificateJobStatus.COMPLETED_WITH_ERRORS:CertificateJobStatus.COMPLETED);jobRepository.save(j);}
}
